import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { environment } from '../../../../environments/environment';
import { firstValueFrom, map, Observable, switchMap } from 'rxjs';
import { SecureStorageService } from '../storage/secure-storage.service';
import { LoginRequestMdl, LoginResponce } from '../../interfaces/login.interface';
import { TostbarService } from '../tost/tostbar.service';

@Injectable()
export class LoginService {
  isinvalid: boolean = false;
  broweserid: string = '';
  constructor(private http: HttpClient, public secureStorage: SecureStorageService, public tost: TostbarService) {
    // this.broweserid = this.secureStorage.getStorage('browserid');
    // if (!this.broweserid) {
    //   mdl.cBroweserid = this.broweserid; //this.secureStorage.getOrCreateBrowserUniqueId(); // This line is problematic as 'mdl' is not defined in the constructor scope.
    //   console.log('LoginService: Logging in with browserid:', mdl.cBroweserid); // This line is problematic as 'mdl' is not defined in the constructor scope.
    //   this.secureStorage.setStorage('browserid', this.broweserid);
    // }
    this.initBroweserid();
    // this.login2({ username:'Alpja', password:'Delta' }).subscribe({
    //   next: response => {
    //     console.warn('Login successful:', response);
    //   },
    //   error: err => {
    //     console.error('Login failed:', err);
    //   }
    // });
    //   console.warn('NETWORK',this.getNetworkInfo())
  }

  initBroweserid() {
    this.broweserid = this.secureStorage.getStorage('browserid');
    if (!this.broweserid) {
      this.broweserid = this.secureStorage.getOrCreateBrowserUniqueId();
      this.secureStorage.setStorage('browserid', this.broweserid);
    }

  }

  async login(mdl: LoginRequestMdl, keepMeLogin: boolean): Promise<boolean> {
    this.isinvalid = false;
    this.initBroweserid();
    try {
      mdl.cBroweserid = this.broweserid;
      mdl.cToken = await this.secureStorage.getFCMToken();
      mdl.bKeepMeLogin = keepMeLogin;
      const res: any = await firstValueFrom(
        this.http.post<LoginResponce>(
          `${environment.cloudUrl}${environment.authservice}/auth/signin`,
          mdl
        )
      );
      if (res && res.msg == 1) {
        if (res.token) {
           this.secureStorage.setEncryptedStorage('temp_socket_token', res.token);
        }
        // Clear force_logout flag on successful login
        localStorage.removeItem('force_logout');
        
        this.secureStorage.setUserInfo(res.userDetail, (keepMeLogin ? res.expir_limit : 0));
        await this.secureStorage.setJWTToken(res.token, (keepMeLogin ? res.expir_limit : 0));
        return true;
      } else {
        // this.tost.openSnackBar(res.value, 'E');
        this.isinvalid = true;
        return false;
      }
    } catch (err) {
      this.tost.openSnackBar(`Login failed ${err && err['message'] ? err['message'] : JSON.stringify(err)}`, 'E', 10000);
      return false;
    }
  }

  getNetworkInfo() {
    try {
      return {
        userAgent: navigator.userAgent, // Browser and OS details
        platform: navigator.platform,  // Platform (Win32, Linux, etc.)
        language: navigator.language,  // User's preferred language
        online: navigator.onLine       // Online status
      };
    } catch (error) {
      return {}
    }
  }
  getIPAddress(): Observable<string> {
    return this.http.get<{ ip: string }>('https://api64.ipify.org?format=json').pipe(
      map(response => response.ip)
    );
  }

  login2(user: { username: string, password: string }) {
    const networkInfo = this.getNetworkInfo();

    return this.getIPAddress().pipe(
      map(ipAddress => ({
        ...user,
        ipAddress,
        ...networkInfo
      })),
      switchMap(loginData => this.http.post('/api/login', loginData)) // Replace with your API endpoint
    );
  }
}